/**
 * ONE01 brand marks — faithful react-native-svg ports of the real logos from
 * the ONE Platform (`Main/one/apps/web/public/*.svg`), so the Expo app uses the
 * same identity as the website. Raw source SVGs live in `src/assets/brand/`.
 *
 * Marks are drawn on a 62×62 grid (product icons) or 181×80 (horizontal
 * wordmarks); category chips on 32×32. Monochrome marks take a `color` prop so
 * they adapt to light/dark; brand-colored marks (Winzi gold, MixStar gradient,
 * Xit green) keep their own fills.
 */
import React from 'react';
import Svg, { Path, Circle, Ellipse, Rect, Defs, LinearGradient, Stop } from 'react-native-svg';

export interface BrandProps {
  size?: number;
  color?: string;
}

/* ─────────────────────────── Auth / provider icons ─────────────────────────── */

